+function extractFromSnapshots(root, comparison, before, after) {
+  const diagnostics = []
+  const artifacts = []
+  const support = []
+  for (const [side, snapshot] of [['old', before], ['new', after]]) {
+    for (const filename of sorted(snapshot.keys())) {
+      const entry = snapshot.get(filename)
