+  fields(trace, [...immutable, 'links', 'unmapped'], [], 'change-map')
+  fields(trace.comparison, ['mode', 'base', 'head', 'requested-base', 'merge-base', 'head-at-capture', 'paths', 'excluded', 'diff-format', 'fingerprint'], [], 'comparison')
